INSERT INTO `tabCRM Form Script` VALUES
('Forecasting Script','2026-10-16 15:40:25.234509','2026-10-16 15:40:25.234509','Administrator','Administrator',0,0,'CRM Deal','Form',1,1,'class CRMDeal {\n    async status() {\n        await this.doc.trigger(\'updateProbability\')\n    }\n    async updateProbability() {\n        let status = await call(\"frappe.client.get_value\", {\n            doctype: \"CRM Deal Status\",\n            fieldname: \"probability\",\n            filters: { name: this.doc.status },\n        })\n\n        this.doc.probability = status.probability\n    }\n}',NULL,NULL,NULL,NULL),
('Product Details Script for CRM Deal','2026-10-16 15:40:25.233084','2026-10-16 15:40:25.233084','Administrator','Administrator',0,0,'CRM Deal','Form',1,1,'class CRMDeal {\n  update_total() {\n    let total = 0\n    let total_qty = 0\n    let net_total = 0\n    let discount_applied = false\n\n    this.doc.products.forEach((d) => {\n      total += d.amount\n      net_total += d.net_amount\n      if (d.discount_percentage > 0) {\n        discount_applied = true\n      }\n    })\n\n    this.doc.total = total\n    this.doc.net_total = net_total || total\n\n    if (!net_total && discount_applied) {\n      this.doc.net_total = net_total\n    }\n  }\n}\n\nclass CRMProducts {\n  products_add() {\n    let row = this.doc.getRow(\'products\')\n    row.trigger(\'qty\')\n    this.doc.trigger(\'update_total\')\n  }\n\n  products_remove() {\n    this.doc.trigger(\'update_total\')\n  }\n\n  async product_code(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    let productCode = row.product_code\n\n    let a = await call(\"crm.fcrm.doctype.crm_products.crm_products.get_product_rate_details\", {\n        product_code: productCode,\n        deal: this.doc.name,\n    })\n    if (!a || row.product_code !== productCode) return\n\n    row.product_name = a.product_name\n    row.rate = a.rate ?? 0\n    row.trigger(\"rate\")\n  }\n\n  qty(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    row.amount = row.qty * row.rate\n    row.trigger(\'discount_percentage\', idx)\n  }\n\n  rate() {\n    let row = this.doc.getRow(\'products\')\n    row.amount = row.qty * row.rate\n    row.trigger(\'discount_percentage\')\n  }\n\n  discount_percentage(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    if (!row.discount_percentage) {\n      row.net_amount = row.amount\n      row.discount_amount = 0\n    }\n    if (row.discount_percentage && row.amount) {\n      row.discount_amount = (row.discount_percentage / 100) * row.amount\n      row.net_amount = row.amount - row.discount_amount\n    }\n    this.doc.trigger(\'update_total\')\n  }\n}',NULL,NULL,NULL,NULL),
('Product Details Script for CRM Lead','2026-10-16 15:40:25.231547','2026-10-16 15:40:25.231547','Administrator','Administrator',0,0,'CRM Lead','Form',1,1,'class CRMLead {\n  update_total() {\n    let total = 0\n    let total_qty = 0\n    let net_total = 0\n    let discount_applied = false\n\n    this.doc.products.forEach((d) => {\n      total += d.amount\n      net_total += d.net_amount\n      if (d.discount_percentage > 0) {\n        discount_applied = true\n      }\n    })\n\n    this.doc.total = total\n    this.doc.net_total = net_total || total\n\n    if (!net_total && discount_applied) {\n      this.doc.net_total = net_total\n    }\n  }\n}\n\nclass CRMProducts {\n  products_add() {\n    let row = this.doc.getRow(\'products\')\n    row.trigger(\'qty\')\n    this.doc.trigger(\'update_total\')\n  }\n\n  products_remove() {\n    this.doc.trigger(\'update_total\')\n  }\n\n  async product_code(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    let productCode = row.product_code\n\n    let a = await call(\"crm.fcrm.doctype.crm_products.crm_products.get_product_rate_details\", {\n        product_code: productCode,\n        deal: this.doc.name,\n    })\n    if (!a || row.product_code !== productCode) return\n\n    row.product_name = a.product_name\n    row.rate = a.rate ?? 0\n    row.trigger(\"rate\")\n  }\n\n  qty(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    row.amount = row.qty * row.rate\n    row.trigger(\'discount_percentage\', idx)\n  }\n\n  rate() {\n    let row = this.doc.getRow(\'products\')\n    row.amount = row.qty * row.rate\n    row.trigger(\'discount_percentage\')\n  }\n\n  discount_percentage(idx) {\n    let row = this.doc.getRow(\'products\', idx)\n    if (!row.discount_percentage) {\n      row.net_amount = row.amount\n      row.discount_amount = 0\n    }\n    if (row.discount_percentage && row.amount) {\n      row.discount_amount = (row.discount_percentage / 100) * row.amount\n      row.net_amount = row.amount - row.discount_amount\n    }\n    this.doc.trigger(\'update_total\')\n  }\n}',NULL,NULL,NULL,NULL);
