olor: #c9d1d9;\\\">department</span><span style=\\\"color: #c9d1d9;\\\">;</span>\\n<span style=\\\"color: #ff7b72;\\\">const</span> <span style=\\\"color: #c9d1d9;\\\">urgency</span> <span style=\\\"color: #c9d1d9;\\\">=</span> <span style=\\\"color: #c9d1d9;\\\">result</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">answers</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">urgency</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">;</span>\\n\\n<span style=\\\"color: #ff7b72;\\\">if</span> <span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">department</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">confidence</span> <span style=\\\"color: #c9d1d9;\\\">&lt;</span> <span style=\\\"color: #79c0ff;\\\">0.6</span><span style=\\\"color: #c9d1d9;\\\">)</span> <span style=\\\"color: #ff7b72;\\\">return</span> <span style=\\\"color: #d2a8ff;\\\">sendToHuman</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">ticket</span><span style=\\\"color: #c9d1d9;\\\">);</span>\\n<span style=\\\"color: #ff7b72;\\\">if</span> <span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">urgency</span> <span style=\\\"color: #c9d1d9;\\\">&gt;</span> <span style=\\\"color: #79c0ff;\\\">0.9</span><span style=\\\"color: #c9d1d9;\\\">)</span> <span style=\\\"color: #ff7b72;\\\">return</span> <span style=\\\"color: #d2a8ff;\\\">escalate</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">ticket</span><span style=\\\"color: #c9d1d9;\\\">);</span>\\n<span style=\\\"color: #ff7b72;\\\">return</span> <span style=\\\"color: #d2a8ff;\\\">routeToTeam</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">department</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">choice</span><span style=\\\"color: #c9d1d9;\\\">,</span> <span style=\\\"color: #c9d1d9;\\\">ticket</span><span style=\\\"color: #c9d1d9;\\\">);</span></code></pre></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"><span style=\\\"color:#000000;\\\">No generated function call, JSON repair loop, or model deciding your business policy. Jev makes the small fuzzy calls and your code handles everything deterministic.</span></p></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"#000000\\\" style=\\\"background-color:#000000;padding:0.0px 0px 12.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"center\\\" valign=\\\"top\\\" style=\\\"color:#000000;font-weight:400;padding:0px 0px;text-align:center;\\\"><h2 style=\\\"color:#000000;font-weight:400;\\\"><span style=\\\"color:#FFFFFF;\\\"><b>Ask everything upfront</b></span></h2></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;border-bottom-width:0px;border-color:#222222;border-left-width:2px;border-right-width:2px;border-style:solid;border-top-width:0px;padding:16.0px 0px 24.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> This is where it gets fun.\\u00a0 </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Say <span style=\\\"color:#188038;\\\">refundRequested</span> only matters for billing tickets. The instinct with a normal LLM is to stage it: classify the ticket, wait, then ask about the refund only if it turned out to be billing. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Jev nudges you to ask everything at once and ignore the answers you don&#39;t need. </p></td></tr><tr><td style=\\\"padding:0px 0px;\\\"><pre style=\\\"background:#282828;border-radius:10px;color:#FFFFFF;line-height:1.5;overflow-wrap:break-word;padding:16px;white-space:pre-wrap;word-break:break-word;\\\"><code><span style=\\\"color: #c9d1d9;\\\">questions</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #c9d1d9;\\\">&#123;</span>\\n  <span style=\\\"color: #c9d1d9;\\\">department</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">choice</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">refundRequested</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">urgency</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">churnRisk</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">frustration</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">score</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n<span style=\\\"color: #c9d1d9;\\\">&#125;</span></code></pre></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> TypeSafe calls this <span style=\\\"font-weight:700;\\\"><b>speculative fan-out</b></span>. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Every question runs against the same state in parallel, so you drop the long chains of serial calls, and their docs show batching 13 questions coming out faster and cheaper than firing them one by one.\\u00a0 </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Once it clicks, you stop thinking in pipelines and start thinking in one wide question. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"></p></td></tr><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"padding-bottom:0px;padding-left:0px;padding-right:0px;padding-top:0px;\\\" class=\\\"dd\\\"><table role=\\\"none\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" class=\\\"bb\\\" style=\\\"margin:0 auto 0 auto;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" class=\\\"bb\\\" style=\\\"width:570px;\\\"><img src=\\\"https://media.beehiiv.com/cdn-cgi/image/fit=scale-down,format=auto,onerror=redirect,quality=80,width=1920,height=3840/uploads/asset/file/ff97b1ed-776f-4905-82be-2a3e23851eda/Frame_2147225140.png?t=1789975474\\\" alt=\\\"\\\" height=\\\"auto\\\" width=\\\"570\\\" style=\\\"display:block;width:100%;border-radius:8px;border-style:solid;border-width:2px;box-sizing:border-box;border-color:#000000;\\\" border=\\\"0\\\"></td></tr></tbody></table></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"#000000\\\" style=\\\"background-color:#000000;padding:0.0px 0px 12.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"center\\\" valign=\\\"top\\\" style=\\\"color:#000000;font-weight:400;padding:0px 0px;text-align:center;\\\"><h2 style=\\\"color:#000000;font-weight:400;\\\"><span style=\\\"color:#FFFFFF;\\\"><b>Confidence becomes useful application state</b></span></h2></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;border-bottom-width:0px;border-color:#222222;border-left-width:2px;border-right-width:2px;border-style:solid;border-top-width:0px;padding:16.0px 0px 24.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Most LLM code throws away uncertainty. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> You get <span style=\\\"color:#188038;\\\">department = billing</span> and move on. But billing at 0.97 (technical at 0.02) and billing at 0.38 (technical at 0.35) both give you the same answer, and only one of them is safe to automate. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Jev keeps that uncertainty around, so you can bake it straight into the product: </p></td></tr><tr><td style=\\\"padding:0px 0px;\\\"><pre style=\\\"background:#282828;border-radius:10px;color:#FFFFFF;line-height:1.5;overflow-wrap:break-word;padding:16px;white-space:pre-wrap;word-break:break-word;\\\"><code><span style=\\\"color: #ff7b72;\\\">if</span> <span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">answer</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">confidence</span> <span style=\\\"color: #c9d1d9;\\\">&gt;</span> <span style=\\\"color: #79c0ff;\\\">0.9</span><span style=\\\"color: #c9d1d9;\\\">)</span> <span style=\\\"color: #c9d1d9;\\\">&#123;</span> <span style=\\\"color: #d2a8ff;\\\">automate</span><span style=\\\"color: #c9d1d9;\\\">();</span> <span style=\\\"color: #c9d1d9;\\\">&#125;</span>\\n<span style=\\\"color: #ff7b72;\\\">else</span> <span style=\\\"color: #ff7b72;\\\">if</span> <span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #c9d1d9;\\\">answer</span><span style=\\\"color: #c9d1d9;\\\">.</span><span style=\\\"color: #c9d1d9;\\\">confidence</span> <span style=\\\"color: #c9d1d9;\\\">&gt;</span> <span style=\\\"color: #79c0ff;\\\">0.6</span><span style=\\\"color: #c9d1d9;\\\">)</span> <span style=\\\"color: #c9d1d9;\\\">&#123;</span> <span style=\\\"color: #d2a8ff;\\\">askForConfirmation</span><span style=\\\"color: #c9d1d9;\\\">();</span> <span style=\\\"color: #c9d1d9;\\\">&#125;</span>\\n<span style=\\\"color: #ff7b72;\\\">else</span> <span style=\\\"color: #c9d1d9;\\\">&#123;</span> <span style=\\\"color: #d2a8ff;\\\">sendToHuman</span><span style=\\\"color: #c9d1d9;\\\">();</span> <span style=\\\"color: #c9d1d9;\\\">&#125;</span></code></pre></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Your thresholds depend on the stakes: filing an email into a folder and issuing a refund deserve very different levels of nerve. </p></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"#000000\\\" style=\\\"background-color:#000000;padding:0.0px 0px 12.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"center\\\" valign=\\\"top\\\" style=\\\"color:#000000;font-weight:400;padding:0px 0px;text-align:center;\\\"><h2 style=\\\"color:#000000;font-weight:400;\\\"><span style=\\\"color:#FFFFFF;\\\"><b>What people are already building</b></span></h2></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;border-bottom-width:0px;border-color:#222222;border-left-width:2px;border-right-width:2px;border-style:solid;border-top-width:0px;padding:16.0px 0px 24.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Jev is barely a week old and the community has completely run with it. The range is wild. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> On the serious end, people are using it as a cheap judgment layer inside bigger systems. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Agent routing is the obvious one: before you send every request to an expensive reasoning model, ask a few nouls first, and only spin up the heavy stuff that&#39;s needed. </p></td></tr><tr><td style=\\\"padding:0px 0px;\\\"><pre style=\\\"background:#282828;border-radius:10px;color:#FFFFFF;line-height:1.5;overflow-wrap:break-word;padding:16px;white-space:pre-wrap;word-break:break-word;\\\"><code><span style=\\\"color: #c9d1d9;\\\">&#123;</span>\\n  <span style=\\\"color: #c9d1d9;\\\">needsReasoning</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">needsWeb</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">needsCode</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">noul</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n  <span style=\\\"color: #c9d1d9;\\\">intent</span><span style=\\\"color: #c9d1d9;\\\">:</span> <span style=\\\"color: #d2a8ff;\\\">choice</span><span style=\\\"color: #c9d1d9;\\\">(</span><span style=\\\"color: #79c0ff;\\\">..</span><span style=\\\"color: #c9d1d9;\\\">.),</span>\\n<span style=\\\"color: #c9d1d9;\\\">&#125;</span></code></pre></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Others use it to check their own LLM output (&quot;did this answer the question? does it make claims it can&#39;t back up?&quot;), letting the generative model stay creative while Jev grades its work. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> The Browser Use team wired it into an agent that books flights in seconds for fractions of a cent, and Vercel benchmarked it as the safety reviewer inside its fx coding tool and is moving it to the default, up to 18x faster than the model it replaced. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> My favorite of the practical bunch is semantic database fields: run your conversations through Jev to get columns like <span style=\\\"color:#188038;\\\">churn_risk = 0.61</span> and <span style=\\\"color:#188038;\\\">purchase_intent = 0.91</span>, then query them with plain SQL. </p></td></tr><tr><td style=\\\"padding:0px 0px;\\\"><pre style=\\\"background:#282828;border-radius:10px;color:#FFFFFF;line-height:1.5;overflow-wrap:break-word;padding:16px;white-space:pre-wrap;word-break:break-word;\\\"><code><span style=\\\"color: #d2a8ff;\\\">SELECT</span> <span style=\\\"color: #c9d1d9;\\\">*</span> <span style=\\\"color: #d2a8ff;\\\">FROM</span> <span style=\\\"color: #c9d1d9;\\\">conversations</span>\\n<span style=\\\"color: #d2a8ff;\\\">WHERE</span> <span style=\\\"color: #c9d1d9;\\\">purchase_intent</span> <span style=\\\"color: #c9d1d9;\\\">&gt;</span> <span style=\\\"color: #79c0ff;\\\">0.8</span> <span style=\\\"color: #d2a8ff;\\\">AND</span> <span style=\\\"color: #c9d1d9;\\\">pricing_sensitivity</span> <span style=\\\"color: #c9d1d9;\\\">&gt;</span> <span style=\\\"color: #79c0ff;\\\">0.7</span><span style=\\\"color: #c9d1d9;\\\">;</span></code></pre></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> I also saw someone <a class=\\\"link\\\" href=\\\"https://link.mail.beehiiv.\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer nofollow\\\"><span>ship a Chrome extension that</span></a> scores your X timeline and blurs the AI slop as you scroll, while <a class=\\\"link\\\" href=\\\"https://link.mail.beehiiv.\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer nofollow\\\"><span>someone else built one</span></a> that skips YouTube sponsor segments with no crowd-sourced database. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> TypeSafe themselves have Jev playing Doom at about 10 decisions a second and racing across Wikipedia by choosing between hundreds of links, and people have since had it play Tetris, run NPCs that judge you, and play Smash Bros. against itself. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"></p></td></tr><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"padding-bottom:0px;padding-left:0px;padding-right:0px;padding-top:0px;\\\" class=\\\"dd\\\"><table role=\\\"none\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"margin:0 auto 0 auto;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"width:100%;\\\"><a href=\\\"https://link.mail.beehiiv.\\\" style=\\\"text-decoration:none !important;\\\"><img src=\\\"https://beehiiv-images-production.s3.amazonaws.com/uploads/asset/file/63c00a1e-3509-406d-a81b-094f79012543/twitter_screenshot_2099925687465570372_1789974344_2ebdee64.jpeg?t=1789974345\\\" alt=\\\"Tweet screenshot\\\" height=\\\"auto\\\" width=\\\"100%\\\" style=\\\"display: block; width: 100%;\\\" border=\\\"0\\\"></a></td></tr></tbody></table></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"></p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"><b>Personally I want to try it on coding-agent tool routing, browser-agent guardrails, email prioritization, moderation queues, and semantic observability for agents.</b></p></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"#B8EF43\\\" style=\\\"background-color:#B8EF43;border-bottom-width:0px;border-color:#222222;border-left-width:2px;border-right-width:2px;border-style:solid;border-top-width:0px;padding:0.0px 0px 12.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"center\\\" valign=\\\"top\\\" style=\\\"color:#000000;font-weight:400;padding:0px 0px;text-align:center;\\\"><h2 style=\\\"color:#000000;font-weight:400;\\\"><span style=\\\"color:#000000;\\\"><b>My take</b></span></h2></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;padding:0.0px 0px 0.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"font-size:0px;line-height:0px;padding:0px 0px 0px;\\\" class=\\\"dd\\\"><table class=\\\"j\\\" role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;border-bottom-left-radius:8px;border-bottom-right-radius:8px;border-bottom-width:2px;border-color:#222222;border-left-width:2px;border-right-width:2px;border-style:solid;border-top-left-radius:0px;border-top-right-radius:0px;border-top-width:0px;padding:16.0px 0px 16.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> We&#39;ve spent the last couple of years shoving nearly every AI problem through the same shape: <span style=\\\"font-weight:400;\\\"><b>messages \\u2192 model \\u2192 text</b></span>, even when all we wanted was a boolean, a category, a score, or a probability. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> We paid for a whole essay to get one number.\\u00a0 </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Jev makes those outputs first-class without pretending to replace reasoning models. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> There&#39;s a mountain of production code out there running <span style=\\\"color:#188038;\\\">llm.generate</span>, then <span style=\\\"color:#188038;\\\">JSON.parse</span>, then <span style=\\\"color:#188038;\\\">if</span>, where the model is doing far more work than the app needs. </p></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> That last <span style=\\\"color:#188038;\\\">if</span> is where Jev gets interesting, and I think a lot of us are about to swap it in. </p></td></tr><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"padding:12px 4px 12px 4px;\\\" class=\\\"dd\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\" class=\\\"d2\\\" style=\\\"background-color:#FFFFFF;border-color:#B8EF43;border-radius:0px 0px 0px 0px;border-style:solid;border-width:0px 0px 0px 2px;\\\"><tbody><tr><td align=\\\"center\\\" valign=\\\"top\\\" style=\\\"padding:7px 12px 7px 12px;\\\" class=\\\"dd\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" align=\\\"center\\\"><tbody><tr><td align=\\\"left\\\" valign=\\\"top\\\" class=\\\"i2\\\"><p style=\\\"color:#2D2D2D;font-weight:500;margin:0px;text-align:left;\\\">That&#39;s it for this one. If you build something weird with Jev, send it my way.</p></td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\"> Until then, <br><span style=\\\"font-weight:700;\\\"><b>Vaibhav</b></span> \\ud83e\\udd1d\\ud83c\\udffb </p></td></tr></tbody></table></td><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td></tr></tbody></table></td><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td></tr></tbody></table></td></tr></tbody></table></td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"\\\"><tbody><tr><td height=\\\"16.0px\\\" style=\\\"line-height:1px;font-size:1px;height:16.0px;\\\"> &nbsp; </td></tr><tr><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\"><tbody><tr><td width=\\\"24.0px\\\" style=\\\"line-height:1px;font-size:1px;width:24.0px;\\\"> &nbsp; </td><td bgcolor=\\\"transparent\\\" style=\\\"background-color:transparent;border-bottom-left-radius:12px;border-bottom-right-radius:12px;border-bottom-width:2px;border-color:#6FE394;border-left-width:2px;border-right-width:2px;border-style:dashed;border-top-left-radius:12px;border-top-right-radius:12px;border-top-width:2px;padding:16.0px 0px 16.0px 0px;box-sizing:border-box;\\\"><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td width=\\\"16\\\" style=\\\"line-height:1px;font-size:1px;width:16px;\\\"> &nbsp; </td><td><table role=\\\"none\\\" width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"table-layout:fixed;\\\"><tbody><tr><td class=\\\"dd\\\" align=\\\"left\\\" style=\\\"padding:0px 0px;text-align:left;word-break:break-word;\\\"><p style=\\\"\\\