INSERT INTO `tabFCRM Note` VALUES
('l6occvp0hj','2026-08-21 10:25:51.276371','2026-08-21 10:25:51.276371','sarah.demo@example.com','sarah.demo@example.com',0,0,'Initial Discovery Call','<p>Had a productive intro call. They\'re evaluating solutions for Q3. Key stakeholders include the CTO and VP of Sales. Budget is pre-approved. Follow up with a tailored proposal.</p>','CRM Lead','CRM-LEAD-2026-00001',0,NULL,NULL,NULL,NULL,NULL,NULL),
('l6okt9dih8','2026-08-26 10:25:51.276371','2026-08-26 10:25:51.276371','sarah.demo@example.com','sarah.demo@example.com',0,0,'Pain Points Identified','<p>Current system lacks reporting and integrations. Team size is growing fast — 40% headcount increase this year. Decision timeline is 6–8 weeks.</p>','CRM Lead','CRM-LEAD-2026-00001',0,NULL,NULL,NULL,NULL,NULL,NULL),
('l6pfjdsnh2','2026-09-06 10:25:51.276371','2026-09-06 10:25:51.276371','sarah.demo@example.com','sarah.demo@example.com',0,0,'Pricing Discussion','<p>Walked through pricing tiers. They prefer an annual plan. Requested a 2-week trial extension. Champion is very engaged — internal buy-in looks strong.</p>','CRM Lead','CRM-LEAD-2026-00004',0,NULL,NULL,NULL,NULL,NULL,NULL),
('l6pgeag55p','2026-09-07 10:25:51.276371','2026-09-07 10:25:51.276371','sarah.demo@example.com','sarah.demo@example.com',0,0,'Competitor Mentioned','<p>Currently trialing a competitor. Our differentiators: better UX, open source, and lower TCO. Send a comparison doc before next call.</p>','CRM Lead','CRM-LEAD-2026-00002',0,NULL,NULL,NULL,NULL,NULL,NULL),
('l6pjrkgncp','2026-08-31 10:25:51.276371','2026-08-31 10:25:51.276371','sarah.demo@example.com','sarah.demo@example.com',0,0,'Demo Feedback','<p>Very positive response to the pipeline view. Asked about custom fields and API access. Needs sign-off from CFO before moving forward.</p>','CRM Lead','CRM-LEAD-2026-00002',0,NULL,NULL,NULL,NULL,NULL,NULL),
('l6pnem2ct1','2026-09-02 10:25:51.276371','2026-09-02 10:25:51.276371','john.demo@example.com','john.demo@example.com',0,0,'Requirements Gathered','<p>Needs CRM + email integration + team collaboration. Currently using spreadsheets. Strong motivation to move to a structured system this quarter.</p>','CRM Lead','CRM-LEAD-2026-00003',0,NULL,NULL,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `tabFCRM Note` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;

